export function mapCharacterThemes<T>(map: (palette: Palette) => T) {
  return {
    "light_miku": map(characterPalettes["miku"].app.light),
    "dark_miku": map(characterPalettes["miku"].app.dark),
    "light_2b": map(characterPalettes["2b"].app.light),
    "dark_2b": map(characterPalettes["2b"].app.dark),
    "light_emilia": map(characterPalettes["emilia"].app.light),
    "dark_emilia": map(characterPalettes["emilia"].app.dark),
  };
}
